function convSerieEmIndicador($serie, $destino)
{
$_SESSION['scriptcase']['cons_tit_ap_associados_pedido']['contr_erro'] = 'on';
  
    $indicador = '';
    switch ($destino) {
        case 'ems2':
            switch ($serie) {
                case 1:
                    $indicador = '3';
                    break;
            }
            break;
        case 'ems5':
            switch ($serie) {
                case 1:
                    $indicador = 'dolar';
                    break;
            }
            break;

    }
    return $indicador;

$_SESSION['scriptcase']['cons_tit_ap_associados_pedido']['contr_erro'] = 'off';
}
