function fecharTransacaoLimbo($programa='', $logSoUltima=false)
{
$_SESSION['scriptcase']['cons_tit_ap_associados_pedido']['contr_erro'] = 'on';
  
    $condProg = '';
    $top      = '';
    $by       = '';
    if($programa <>  ''){
        $condProg   = " and cod_programa = '$programa' " ;
    }
    if($logSoUltima == true) {
        $top = " top 1";
        $by = " order by transacao_id desc";
