function criarDirNivel($diretorioAtual,$qtVoltarNiveis,$dirCriar)
{
$_SESSION['scriptcase']['cons_tit_ap_associados_pedido']['contr_erro'] = 'on';
  
    $erro = '';
    $erroCriarDiretorio = '';
    $novoCaminho = '';
    if($diretorioAtual == ''){
        $diretorioAtual = getcwd();
    }

    $aCaminho = $this->voltarNivelDir($diretorioAtual,$qtVoltarNiveis);
    $novoCaminho = $aCaminho['diretorio'];
    $separador   = $aCaminho['separador'];
    $erroVoltarNivel = $aCaminho['erro'];
    $novoCaminho .= "{$separador}{$dirCriar}";
    $erro .= "<br />".$erroVoltarNivel;
    if(!is_dir($novoCaminho)){
        $erroCriarDiretorio .= $this->criarDiretorio($novoCaminho);
    }else{
        $erroCriarDiretorio = "Diretório já estava Criado";
    }
    $erro .= "<br />$erroCriarDiretorio";
    return $erro;

$_SESSION['scriptcase']['cons_tit_ap_associados_pedido']['contr_erro'] = 'off';
}
function voltarNivelDir($diretorioAtual,$qtVoltarNiveis)
{
$_SESSION['scriptcase']['cons_tit_ap_associados_pedido']['contr_erro'] = 'on';
  
    $novoCaminho = '';
    $erro = '';
    if(strstr($diretorioAtual,"/") <> false){
        $separador = "/";
    }else{
        $separador = "\\";
    }
    $aDiretorios = explode($separador,$diretorioAtual);
    if(is_array($aDiretorios)){
        $tam = count($aDiretorios);
        if($qtVoltarNiveis < $tam + 1){
            for($i=0;$i< $tam - $qtVoltarNiveis; $i++){
                $diretorio = $aDiretorios[$i];
                $novoCaminho =  $this->util_incr_valor($novoCaminho,$diretorio,'\\');
            }
        }else{
            $erro = "Qt. Niveis a voltar é maior que a quantidade de niveis do diretório atual";
        }
    }
    $aRetorno = array('erro' => $erro, 'diretorio' => $novoCaminho, 'separador' => $separador);
   return $aRetorno;

$_SESSION['scriptcase']['cons_tit_ap_associados_pedido']['contr_erro'] = 'off';
}
function buscarTitAssociadosContainer($containerId)
{
$_SESSION['scriptcase']['cons_tit_ap_associados_pedido']['contr_erro'] = 'on';
  
    $listaIdTitulos = ''; 
    $aRetorno = $this->retornoMultReg('pub.pagtos_container','num_id_tit_ap', " container_id = $containerId order by num_id_tit_ap ","espec" );
    if(is_array($aRetorno)){
        for($i =0;$i < count($aRetorno);$i++){
            if($listaIdTitulos == ''){
                $listaIdTitulos = $aRetorno[$i]['num_id_tit_ap'];
            }
            else{
                $listaIdTitulos .= ','.$aRetorno[$i]['num_id_tit_ap'];
            }
        }
    }
    return $listaIdTitulos;

$_SESSION['scriptcase']['cons_tit_ap_associados_pedido']['contr_erro'] = 'off';
}
function buscarTotPagoContainer($containerId,$moeda='')
{
$_SESSION['scriptcase']['cons_tit_ap_associados_pedido']['contr_erro'] = 'on';
  
    $vl = 0;
    $listaIDTitulos     = $this->buscarTitAssociadosContainer($containerId);
    
    $aTitulos 			  = explode(",",$listaIDTitulos);
    if(is_array($aTitulos)){
        for($i=0;$i < count($aTitulos);$i++){
            $titID = $aTitulos[$i];
            if($titID == ''){$titID = 0;}
            switch($moeda){
                case 'dolar':
                    $vl_tit_corrente = $this->buscarVlMoeda($titID,'','dolar');
                    break;
                default:
                    $vl_tit_corrente = $this->buscarVlMoeda($titID);
            }
            $vl += $vl_tit_corrente;
        }
    }
    return $vl;

$_SESSION['scriptcase']['cons_tit_ap_associados_pedido']['contr_erro'] = 'off';
}
