              {
                  $tmp_cmd .= " and (" . $_SESSION['sc_session'][$this->Ini->sc_page]['cons_tit_ap_associados_pedido']['where_pesq_dyn'] . ")"; 
              }
              else
              {
                  $tmp_cmd = " where (" . $_SESSION['sc_session'][$this->Ini->sc_page]['cons_tit_ap_associados_pedido']['where_pesq_dyn'] . ")"; 
              }
          }
          $_SESSION['sc_session'][$this->Ini->sc_page]['cons_tit_ap_associados_pedido']['where_pesq'] = $tmp_cmd;
          unset($_SESSION['sc_session'][$this->Ini->sc_page]['cons_tit_ap_associados_pedido']['fast_search']);
