   function nm_protect_num_cons_tit_ap_associados_pedido($name, &$val)
   {
       if (empty($val))
       {
          return;
       }
       $Nm_numeric = array();
       $Nm_numeric[] = "cdn_fornecedor";
       $Nm_numeric[] = "num_fatur_ap";
       $Nm_numeric[] = "log_sdo_tit_ap";
       $Nm_numeric[] = "log_tit_ap_estordo";
       $Nm_numeric[] = "val_origin_tit_ap";
       $Nm_numeric[] = "val_cm_tit_ap";
       $Nm_numeric[] = "val_pagto_tit_ap";
       $Nm_numeric[] = "val_sdo_tit_ap";
       $Nm_numeric[] = "num_id_tit_ap";
       $Nm_numeric[] = "";
       $simb_grp = (isset($_SESSION['scriptcase']['reg_conf']['grup_num'])) ? $_SESSION['scriptcase']['reg_conf']['grup_num'] : ".";
       $simb_dec = (isset($_SESSION['scriptcase']['reg_conf']['dec_num']))  ? $_SESSION['scriptcase']['reg_conf']['dec_num']  : ",";
       $simb_neg = (isset($_SESSION['scriptcase']['reg_conf']['simb_neg'])) ? $_SESSION['scriptcase']['reg_conf']['simb_neg'] : "-";
       if (in_array($name, $Nm_numeric))
       {
           if (is_array($val))
           {
               foreach ($val as $cada_val)
               {
                  $tmp_pos = (is_string($cada_val)) ? strpos($cada_val, "##@@") : false;
                  if ($tmp_pos !== false)
                   {
                      $cada_val = substr($cada_val, 0, $tmp_pos);
                  }
                  for ($x = 0; $x < strlen($cada_val); $x++)
                  {
                      if (($cada_val[$x] < 0 || $cada_val[$x] > 9) && $cada_val[$x] != $simb_grp && $cada_val[$x] != $simb_dec && $cada_val[$x] != $simb_neg)
                      {
                          $val = array();
                          return;
                      }
                   }
               }
               return;
           }
           $cada_val = $val;
           $tmp_pos = (is_string($cada_val)) ? strpos($cada_val, "##@@") : false;
           if ($tmp_pos !== false)
            {
               $cada_val = substr($cada_val, 0, $tmp_pos);
           }
           for ($x = 0; $x < strlen($cada_val); $x++)
           {
               if (($cada_val[$x] < 0 || $cada_val[$x] > 9) && $cada_val[$x] != $simb_grp && $cada_val[$x] != $simb_dec && $cada_val[$x] != $simb_neg)
               {
                   $val = 0;
                   return;
               }
           }
       }
   }
   function cons_tit_ap_associados_pedido_pack_protect_string($sString)
   {
      $sString = (string) $sString;
      if (!empty($sString))
      {
         if (function_exists('NM_is_utf8') && NM_is_utf8($sString))
         {
             return $sString;
         }
         else
         {
             return sc_htmlentities($sString);
         }
      }
      elseif ('0' === $sString || 0 === $sString)
      {
         return '0';
      }
      else
      {
         return '';
      }
   }

    function cons_tit_ap_associados_pedido_pdf_progress_call($message, $Nm_lang, $flushBuffer = false) {
        $message = trim($message);
        if ('off' == $message)
        {
            $bol_end = TRUE;
        }
        elseif (false !== strpos($message, 'HDOC_#NM#_'))
        {
            $bol_end    = FALSE;
            $arr_partes = explode('_#NM#_', $message);
            if (4 == sizeof($arr_partes))
            {
                $int_size = $arr_partes[0];
                $str_msg  = ('F' == $arr_partes[2]) ? $Nm_lang['lang_pdff_frmt_page']  : $Nm_lang['lang_pdff_wrtg'];
                $str_msg .= $arr_partes[2];
                $int_step = ('F' == $arr_partes[2]) ? floor($int_size * 0.9) : floor($int_size * 0.95);
            }
            else
            {
                $bol_load = FALSE;
            }
        }
        else
        {
            $bol_end    = FALSE;
            $arr_partes = explode('_#NM#_', $message);
            if (3 == sizeof($arr_partes))
            {
                $int_size = $arr_partes[0];
                $int_step = $arr_partes[1];
                $str_msg  = $arr_partes[2];
            }
            else
            {
                $bol_load = FALSE;
            }
        }
        $return_message = $int_size . '!#!' . $int_step . '!#!' . ($bol_end ? '1' : '0') . '!#!' . ($bol_end ? $Nm_lang['lang_pdff_fnsh'] : $str_msg);
?>
<script type="text/javascript">
if (window.parent && typeof window.parent.updateProgressBar === "function") {
    window.parent.updateProgressBar("<?php echo trim($return_message); ?>");
}
</script>
<?php
        global $script_case_init;
        if ($flushBuffer && $_SESSION['sc_session'][$script_case_init]['cons_tit_ap_associados_pedido']['opcao'] != 'print') {
            $bufferSize = @ini_get('output_buffering');
            if ('' != $bufferSize) {
                echo str_repeat('&nbsp;', $bufferSize * 5);
            }
        }
        flush();
    }

    function _c419bce6394634208c0a8bbe83b8e350_initializeFixedColumnsGrid($script_case_init)
    {
        if (!isset($_SESSION['sc_session'][$script_case_init]['cons_tit_ap_associados_pedido']['fixed_columns_grid'])) {
            $_SESSION['sc_session'][$script_case_init]['cons_tit_ap_associados_pedido']['fixed_columns_grid'] = '';
        }
    }

    function _c419bce6394634208c0a8bbe83b8e350_saveFixedColumnsGrid($index, $action, $script_case_init)
    {
        _c419bce6394634208c0a8bbe83b8e350_initializeFixedColumnsGrid($script_case_init);

        if ('on' == $action) {
            $_SESSION['sc_session'][$script_case_init]['cons_tit_ap_associados_pedido']['fixed_columns_grid'] = $index;
        } elseif (0 < $index) {
            $_SESSION['sc_session'][$script_case_init]['cons_tit_ap_associados_pedido']['fixed_columns_grid'] = $index - 1;
        } else {
            $_SESSION['sc_session'][$script_case_init]['cons_tit_ap_associados_pedido']['fixed_columns_grid'] = '';
        }

        echo json_encode(
            array(
                'status' => 'ok'
            )
        );
        exit;
    }

    function _c419bce6394634208c0a8bbe83b8e350_loadFixedColumnsGrid($script_case_init)
    {
        _c419bce6394634208c0a8bbe83b8e350_initializeFixedColumnsGrid($script_case_init);

        echo json_encode(
            array(
                'status' => 'ok',
                'last_index' =>$_SESSION['sc_session'][$script_case_init]['cons_tit_ap_associados_pedido']['fixed_columns_grid']
            )
        );
        exit;
    }

?>
